const embedding = $input.item.json.embedding;
const vectorStr = '[' + embedding.join(',') + ']';
return { json: { embedding_str: vectorStr } };

const raw = String($('Execute Workflow Trigger').item.json.message?.text || '');
const intent = String($json.intent || 'tool');
const similarity = Number($json.similarity || 0);

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D');
}

const text = normalize(raw);

const hasGoldCue = /(vang|gold|sjc|9999)/.test(text);
const hasNewsCue = /(tin tuc|doc bao|bao hom nay|news|vnexpress|bao moi)/.test(text);
const hasWeatherCue = /(thoi tiet|weather|nhiet do|do am|mua|du bao|forecast)/.test(text);

const hasCalendarCue =
  /\b(calendar|google calendar|xem lich|lich hom nay|lich ngay mai|lich tuan nay|lich tuan sau|tao lich|dat lich|them lich|tao su kien|dat su kien|su kien|hop voi|meeting|kiem tra lich ranh|kiem tra lich ban|co ranh|ranh luc|xoa lich|huy lich|tim lich|cuoi tuan nay|cuoi tuan sau|thu [2-7]|chu nhat)\b/.test(text);

const hasGmailCue =
  /\b(gmail|mail|email|inbox|hop thu|hop thu den|xem mail|xem email|doc mail|doc email|gui mail|gui email|gui nhap|gui email nhap|gui mail nhap|soan mail|soan email|viet nhap email|draft email|draft mail|tim mail|tim email|tra loi mail|tra loi email|mail moi|email moi|check mail|check email|kiem tra mail|kiem tra email|send mail|send email|send draft|read mail|read email|reply mail|reply email|search mail|search email)\b/.test(text);

// Drive cues mở rộng: thêm share/chia sẻ/cấp quyền kể cả khi user không gõ chữ "file".
const hasDriveCue =
  /\b(drive|google drive|xem drive|file drive|tim file|kiem file|tim tep|kiem tep|tim trong drive|danh sach file|file gan day|thong tin file|chi tiet file|file info|metadata file|noi dung file|doc file|read file|tao folder|tao thu muc|create folder|tao file|tao tep|create file|upload file|download file|tai file|tai tep|luu file|luu tep|share file|share tep|share drive|share folder|chia se file|chia se tep|chia se folder|chia se thu muc|chia se drive|cap quyen file|cap quyen tep|cap quyen folder|cap quyen thu muc|give access|give access file|give access folder|phan quyen file|phan quyen folder|quyen xem|quyen sua|quyen edit|quyen comment|quyen nhan xet|xuat file|export file|doi ten file|rename file|move file|di chuyen file|chuyen file|copy file|nhan ban file|duplicate file|xoa file|delete file|xoa folder|xoa thu muc|delete folder|folder|thu muc)\b/.test(text);

// Câu có email + động từ chia sẻ/cấp quyền thường là Drive share, không phải Gmail.
const hasDriveShareWithEmail =
  /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(text) &&
  /\b(share|chia se|cap quyen|give access|phan quyen|quyen xem|quyen sua|quyen edit|quyen comment|quyen nhan xet)\b/.test(text);

const hasSearchCue = /(tim|tra cuu|search|google|duckduckgo|wiki|wikipedia|cho toi biet|thong tin ve|noi ve)/.test(text);
const hasResearchCue = /(nghien cuu|paper|pubmed|journal|drug|interaction|gdp|imf|world bank|statista|bao cao|report|dataset)/.test(text);
const hasFactCue = /(ai la|la gi|o dau|nam nao|khi nao|bao nhieu|how|what|who|when|where)/.test(text);
const hasYearOrMetric = /(19\d{2}|20\d{2}|\d+\s*(usd|vnd|%|trieu|ty|billion|million))/i.test(text);

let routeIntent = intent;
let routeReason = `vector:${intent}:${similarity.toFixed(3)}`;

if (hasGoldCue || hasNewsCue || hasWeatherCue || hasCalendarCue || hasGmailCue || hasDriveCue || hasDriveShareWithEmail) {
  routeIntent = 'tool';
  routeReason = hasDriveShareWithEmail ? 'keyword:drive_share_email' : 'keyword:direct_tool';
} else if ((hasSearchCue || hasResearchCue || hasFactCue || hasYearOrMetric) && similarity < 0.78) {
  routeIntent = 'tool';
  routeReason = 'keyword_override_search';
}

return [{
  json: {
    ...$json,
    raw,
    normalizedText: text,
    routeIntent,
    routeReason
  }
}];

// =============================================
// TOOL ROUTER
// Them tool moi: 1 dong workflowMap + 1 dong detect
// =============================================
const workflowMap = {
  gold:     'Sub-workflow: Giá Vàng',
  news:     'Sub-workflow: Tin Tức',
  search:   'Sub-workflow: Tìm Kiếm Web',
  weather:  'Sub-workflow: Thời Tiết',
  calendar: 'Sub-workflow: Google Calendar Master',
  gmail:    'Sub-workflow: Google Gmail Master',
  drive:    'Sub-workflow: Google Drive Master',
};

const input = $('Execute Workflow Trigger').item.json || {};
const message = input.message || input.body?.message || {};
const raw =
  message.text ||
  input.text ||
  input.rawText ||
  '';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D');
}

const text = normalize(raw);

let toolKey = null;

const hasGoldCue =
  text.includes('vang') ||
  text.includes('gold') ||
  text.includes('sjc');

const hasNewsCue =
  text.includes('tin tuc') ||
  text.includes('doc bao') ||
  text.includes('bao hom nay') ||
  text.includes('news');

const hasWeatherCue =
  text.includes('thoi tiet') ||
  text.includes('weather') ||
  text.includes('nhiet do') ||
  text.includes('do am') ||
  text.includes('du bao');

const hasCalendarCue =
  /\b(calendar|google calendar|xem lich|lich hom nay|lich ngay mai|lich tuan nay|lich tuan sau|tao lich|dat lich|them lich|tao su kien|dat su kien|su kien|hop voi|meeting|kiem tra lich ranh|kiem tra lich ban|co ranh|ranh luc|xoa lich|huy lich|tim lich|cuoi tuan nay|cuoi tuan sau|thu [2-7]|chu nhat)\b/.test(text);

const hasGmailCue =
  /\b(gmail|mail|email|inbox|hop thu|hop thu den|xem mail|xem email|doc mail|doc email|gui mail|gui email|gui nhap|gui email nhap|gui mail nhap|soan mail|soan email|viet nhap email|draft email|draft mail|tim mail|tim email|tra loi mail|tra loi email|mail moi|email moi|check mail|check email|kiem tra mail|kiem tra email|send mail|send email|send draft|read mail|read email|reply mail|reply email|search mail|search email)\b/.test(text);

const hasDriveCue =
  /\b(drive|google drive|xem drive|file drive|tim file|kiem file|tim tep|kiem tep|tim trong drive|danh sach file|file gan day|thong tin file|chi tiet file|file info|metadata file|noi dung file|doc file|read file|tao folder|tao thu muc|create folder|tao file|tao tep|create file|upload file|download file|tai file|tai tep|luu file|luu tep|share file|share tep|share drive|share folder|chia se file|chia se tep|chia se folder|chia se thu muc|chia se drive|cap quyen file|cap quyen tep|cap quyen folder|cap quyen thu muc|give access|give access file|give access folder|phan quyen file|phan quyen folder|quyen xem|quyen sua|quyen edit|quyen comment|quyen nhan xet|xuat file|export file|doi ten file|rename file|move file|di chuyen file|chuyen file|copy file|nhan ban file|duplicate file|xoa file|delete file|xoa folder|xoa thu muc|delete folder|folder|thu muc)\b/.test(text);

const hasDriveShareWithEmail =
  /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(text) &&
  /\b(share|chia se|cap quyen|give access|phan quyen|quyen xem|quyen sua|quyen edit|quyen comment|quyen nhan xet)\b/.test(text);

// Thu tu quan trong:
// Drive phai nam truoc Search, vi "tim file ..." co chu "tim".
// Drive share co email phai nam truoc Gmail, vi co chu email.
if (hasGoldCue) {
  toolKey = 'gold';
} else if (hasNewsCue) {
  toolKey = 'news';
} else if (hasWeatherCue) {
  toolKey = 'weather';
} else if (hasCalendarCue) {
  toolKey = 'calendar';
} else if (hasDriveCue || hasDriveShareWithEmail) {
  toolKey = 'drive';
} else if (hasGmailCue) {
  toolKey = 'gmail';
} else if (
  text.includes('tim') ||
  text.includes('search') ||
  text.includes('tra cuu') ||
  text.includes('cho toi biet') ||
  text.includes('thong tin ve') ||
  text.includes('duckduckgo') ||
  text.includes('google')
) {
  toolKey = 'search';
} else if (
  /[\d+\-*\/()%.]+/.test(text) &&
  (
    text.includes('tinh') ||
    text.includes('bang') ||
    text.includes('cong') ||
    text.includes('nhan') ||
    text.includes('chia') ||
    text.includes('tru')
  )
) {
  const match = raw.match(/[\d+\-*\/().%\s]+/);
  if (match) {
    try {
      const result = eval(match[0].trim());
      return [{
        json: {
          route: 'calc_done',
          response: 'Ket qua: ' + match[0].trim() + ' = ' + result,
          text: raw,
        },
      }];
    } catch (e) {}
  }

  return [{
    json: {
      route: 'calc_done',
      response: 'Khong the tinh duoc phep tinh nay.',
      text: raw,
    },
  }];
}

if (toolKey) {
  return [{
    json: {
      route: 'sub',
      workflowName: workflowMap[toolKey],
      toolKey,
      text: raw,
      rawText: raw,
      message,
      payload: input,
      chatId: message.chat?.id || input.chatId || input.body?.chatId,
    },
  }];
}

return [{
  json: {
    route: 'ai',
    text: raw,
    rawText: raw,
    message,
    payload: input,
    chatId: message.chat?.id || input.chatId || input.body?.chatId,
  },
}];

const workflows = $input.item.json.data;
const targetName = $('Tool Router').item.json.workflowName;
const message = $('Execute Workflow Trigger').item.json.message;

const found = workflows.find(w => w.name === targetName);
if (!found) {
  // Fallback: return error response
  return [{ json: { workflowId: null, error: 'Workflow not found: ' + targetName, message } }];
}
return [{ json: { workflowId: found.id, message } }];
